import test from 'node:test';
import assert from 'node:assert/strict';
import { createLiveEditorialCycle } from '../src/editorial/live-cycle.js';
import { renderAIIntelligenceDaily } from '../src/intelligence/daily-masters.js';
import { narrativeFingerprint, patchPublicNarrative } from '../src/production/public-narrative-maintenance.js';
const cycle = () => createLiveEditorialCycle();
const unit = (category) => cycle().units.find(item => item.category === category);
const article = (html) => html.match(/<article\b[^>]*>[\s\S]*<\/article>/i)[0];
class Fake {
    patches = [];
    post;
    constructor(post) { this.post = structuredClone(post); }
    async readPost() { return structuredClone(this.post); }
    async patchPost(postId, input) { this.patches.push(postId); this.post = { ...this.post, title: input.title, content: article(input.content) }; return this.readPost(); }
    async fetchPublic() { return { status: 200, body: `<html><body>${this.post.title}${this.post.content}</body></html>` }; }
}
test('public AI prose removes repeated analytical labels while internal whyItMatters remains', () => { const ai = unit('AI_INTELLIGENCE'); const view = ai.viewModel; assert.ok(view.issues.every(item => item.whyItMatters && item.evidenceRefs.length)); assert.doesNotMatch(ai.render.html, /무슨 일이 있었나|왜 중요한가|핵심 내용|시장 연결/); const issueSection = ai.render.html.match(/data-section="ai-산업-인텔리전스"[\s\S]*?data-section="산업-기업-연결"/)?.[0] ?? ''; assert.equal((issueSection.match(/<ul\b/g) ?? []).length, 0); assert.ok((issueSection.match(/<p\b/g) ?? []).length >= 6); });
test('industry connection requires explanation and evidence and never renders a title-only card', () => { const view = structuredClone(unit('AI_INTELLIGENCE').viewModel); view.industryConnections = [{ title: '제목만', explanation: '', connectedCompanies: ['A'], connectedIndustries: [], evidenceRefs: ['e1'], optionalWatchPoint: null }, { title: '근거 없음', explanation: '연결 설명', connectedCompanies: ['A'], connectedIndustries: [], evidenceRefs: [], optionalWatchPoint: null }, { title: '검증 연결', explanation: '공식 자료가 연결 구조를 설명한다.', connectedCompanies: ['A'], connectedIndustries: ['클라우드'], evidenceRefs: ['e1'], optionalWatchPoint: null }]; const html = renderAIIntelligenceDaily(view).html; assert.doesNotMatch(html, /제목만|근거 없음/); assert.match(html, /검증 연결[\s\S]*공식 자료가 연결 구조를 설명한다/); });
test('Korea public HTML hides internal brokerage warning and keeps narrative prose', () => { const korea = unit('KOREA_MARKET'); assert.ok(korea.warnings.includes('BROKERAGE_RESEARCH_NOT_AVAILABLE')); assert.doesNotMatch(korea.render.html, /BROKERAGE_RESEARCH_NOT_AVAILABLE|증권사 원문 리서치가 확보되지 않아/); assert.match(korea.render.html, /코스피에서는 외국인이 약 1\.75조원을 순매도/); });
test('AI public patch is target-isolated, performs one patch and preserves source set', async () => { const ai = unit('AI_INTELLIGENCE'); const current = article(ai.render.html); const old = current.replace('<h3 style="margin:0 0 12px;color:#03162e;font-size:20px">', '<strong>왜 중요한가:</strong><h3 style="margin:0 0 12px;color:#03162e;font-size:20px">'); const adapter = new Fake({ postId: '4294902999154862199', title: ai.title, content: old, status: 'PUBLISHED', url: 'https://motusnova.blogspot.com/2026/10/ai.html', labels: [ai.render.label] }); const result = await patchPublicNarrative({ unit: ai, postId: '4294902999154862199', expectedState: 'PUBLISHED', expectedBeforeFingerprint: narrativeFingerprint(old), adapter }); assert.equal(result.patchCount, 1); assert.deepEqual(adapter.patches, ['4294902999154862199']); assert.equal(result.state, 'PUBLISHED'); assert.equal(result.validation?.repeatedAnalyticalLabels, 0); assert.equal(result.validation?.titleOnlyConnectionCount, 0); assert.equal(result.sourceValidation, true); });
test('Korea Draft narrative patch remains DRAFT and has no publish capability', async () => { const korea = unit('KOREA_MARKET'); const current = article(korea.render.html); const old = current.replace('대형주에서 성장 업종으로 이동한 수급이 다음 거래일에도 이어지는지가 핵심이다.', '검증된 최신 국내 증권사 원문 리서치가 확보되지 않아 기관 전망을 덧붙이지 않았다.'); const adapter = new Fake({ postId: '568850689418151231', title: korea.title, content: old, status: 'DRAFT', url: null, labels: [korea.render.label] }); const result = await patchPublicNarrative({ unit: korea, postId: '568850689418151231', expectedState: 'DRAFT', expectedBeforeFingerprint: narrativeFingerprint(old), adapter }); assert.equal(result.patchCount, 1); assert.equal(result.state, 'DRAFT'); assert.equal(adapter.post.status, 'DRAFT'); assert.equal(result.validation?.internalWarningCount, 0); assert.equal('publishPost' in adapter, false); });
test('U.S. chart caption correction remains preserved by the narrative renderer', () => { const html = unit('US_MARKET').render.html; assert.match(html, /2026년 9월 29일~10월 5일 정규장 종가/); assert.doesNotMatch(html, /2026년 9월 10~16일 정규장 종가/); });
